{"argv": ["python3", "-c", "import harness as H, numpy as np
recs=H.data()
def fit(FN,lam=15.0):
    X=H.Xmat(FN,recs); y=np.array([r[2] for r in recs])
    mu=X.mean(0); sd=X.std(0)
    A=np.hstack([np.ones((len(X),1)),(X-mu)/sd])
    R=lam*np.eye(A.shape[1]); R[0,0]=0
    b=np.linalg.solve(A.T@A+R,A.T@y)
    m,p,_,_,_=H.lopocv(['1']+FN,recs,lam=lam)
    return [round(float(v),6) for v in mu],[round(float(v),6) for v in sd],[round(float(v),6) for v in b],round(float(m),4)
for nm,FN in [('cub',['s','s*s/10.0','s*s*s/100.0']),('sat',['1-2.718281828**(-s/20.0)','1-2.718281828**(-s/45.0)'])]:
    print(nm,fit(FN))
"]}
